#[derive(Debug, Clone)]
pub struct Resend {
    pub config: ClientConfig,
    pub emails: EmailsNamespace,
    pub receiving_emails: ReceivingEmailsNamespace,
    pub domains: DomainsNamespace,
    pub api_keys: ApiKeysNamespace,
    pub oauth: OauthNamespace,
    pub templates: TemplatesNamespace,
    pub audiences: AudiencesNamespace,
    pub contacts: ContactsNamespace,
    pub broadcasts: BroadcastsNamespace,
    pub webhooks: WebhooksNamespace,
    pub segments: SegmentsNamespace,
    pub topics: TopicsNamespace,
    pub contact_properties: ContactPropertiesNamespace,
    pub logs: LogsNamespace,
    pub automations: AutomationsNamespace,
    pub events: EventsNamespace,
    pub suppressions: SuppressionsNamespace,
    pub usage: UsageNamespace,
    pub inboxes: InboxesNamespace,
}

impl Resend {
    pub fn new(config: ClientConfig) -> Self {
        Self {
            emails: EmailsNamespace::new(config.clone()),
            receiving_emails: ReceivingEmailsNamespace::new(config.clone()),
            domains: DomainsNamespace::new(config.clone()),
            api_keys: ApiKeysNamespace::new(config.clone()),
            oauth: OauthNamespace::new(config.clone()),
            templates: TemplatesNamespace::new(config.clone()),
            audiences: AudiencesNamespace::new(config.clone()),
            contacts: ContactsNamespace::new(config.clone()),
            broadcasts: BroadcastsNamespace::new(config.clone()),
            webhooks: WebhooksNamespace::new(config.clone()),
            segments: SegmentsNamespace::new(config.clone()),
            topics: TopicsNamespace::new(config.clone()),
            contact_properties: ContactPropertiesNamespace::new(config.clone()),
            logs: LogsNamespace::new(config.clone()),
            automations: AutomationsNamespace::new(config.clone()),
            events: EventsNamespace::new(config.clone()),
            suppressions: SuppressionsNamespace::new(config.clone()),
            usage: UsageNamespace::new(config.clone()),
            inboxes: InboxesNamespace::new(config.clone()),
            config,
        }
    }

    /// Turns SDK logging on and configures it. Logging is OFF by default — this
    /// SDK reports nothing until you call this (or construct the client with a
    /// `ClientConfig` whose logging is enabled). Reports go to the endpoint this
    /// build was generated with, or to the `endpoint` you pass; with neither,
    /// nothing is sent.
    ///
    /// This ALWAYS enables logging — `enabled` on the passed config is ignored,
    /// since `LoggingConfig::default()` keeps logging disabled at rest and
    /// honouring it would make the obvious "configure and turn on" call a
    /// silent no-op. PII filtering remains on unless the supplied config
    /// explicitly sets `filter_pii` to false.
    pub fn set_logging_config(&mut self, logging: Option<LoggingConfig>) -> LoggingConfig {
        if let Some(next) = logging {
            self.config.logging = next;
        }
        self.config.logging.enabled = true;
        self.emails = EmailsNamespace::new(self.config.clone());
        self.receiving_emails = ReceivingEmailsNamespace::new(self.config.clone());
        self.domains = DomainsNamespace::new(self.config.clone());
        self.api_keys = ApiKeysNamespace::new(self.config.clone());
        self.oauth = OauthNamespace::new(self.config.clone());
        self.templates = TemplatesNamespace::new(self.config.clone());
        self.audiences = AudiencesNamespace::new(self.config.clone());
        self.contacts = ContactsNamespace::new(self.config.clone());
        self.broadcasts = BroadcastsNamespace::new(self.config.clone());
        self.webhooks = WebhooksNamespace::new(self.config.clone());
        self.segments = SegmentsNamespace::new(self.config.clone());
        self.topics = TopicsNamespace::new(self.config.clone());
        self.contact_properties = ContactPropertiesNamespace::new(self.config.clone());
        self.logs = LogsNamespace::new(self.config.clone());
        self.automations = AutomationsNamespace::new(self.config.clone());
        self.events = EventsNamespace::new(self.config.clone());
        self.suppressions = SuppressionsNamespace::new(self.config.clone());
        self.usage = UsageNamespace::new(self.config.clone());
        self.inboxes = InboxesNamespace::new(self.config.clone());
        self.config.logging.clone()
    }
}
